node <<'JS'
const { chromium } = require('/tmp/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await page.goto('http://127.0.0.1:5055/index.html', { waitUntil: 'domcontentloaded' });
  // Simulate mobile loaded chrome without needing the API
  const result = await page.evaluate(() => {
    document.body.classList.add('trace-loaded-mobile', 'playback-ready');
    const h1 = document.getElementById('appTitle');
    const brand = h1.textContent;
    h1.textContent = 'Beijing taxi sample (12,345 points)';
    h1.title = h1.textContent;
    const header = document.querySelector('header');
    const back = document.getElementById('mobileBackBtn');
    const help = document.getElementById('uiTourRelaunch');
    const hr = header.getBoundingClientRect();
    const tr = h1.getBoundingClientRect();
    return {
      brand,
      title: h1.textContent,
      scrollWidth: document.documentElement.scrollWidth,
      clientWidth: document.documentElement.clientWidth,
      headerH: Math.round(hr.height),
      titleClient: Math.round(tr.width),
      titleScroll: Math.round(h1.scrollWidth),
      ellipsis: h1.scrollWidth > h1.clientWidth + 1,
      backVisible: getComputedStyle(back).display !== 'none',
      helpVisible: getComputedStyle(help).display !== 'none',
      titleRight: getComputedStyle(h1).textAlign,
    };
  });
  console.log('mobile', JSON.stringify(result, null, 2));
  await page.screenshot({ path: '/tmp/mobile-header-live-check.png' });

  // Desktop idle brand length check at 900
  await page.setViewportSize({ width: 900, height: 800 });
  await page.goto('http://127.0.0.1:5055/index.html', { waitUntil: 'domcontentloaded' });
  const desk = await page.evaluate(() => {
    const h1 = document.getElementById('appTitle');
    const header = document.querySelector('header');
    return {
      brand: h1.textContent,
      scrollWidth: document.documentElement.scrollWidth,
      clientWidth: document.documentElement.clientWidth,
      headerH: Math.round(header.getBoundingClientRect().height),
      h1MaxWidth: getComputedStyle(h1).maxWidth,
    };
  });
  console.log('desktop900', JSON.stringify(desk, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
